  /// Each layer's children, in Figma's order: the tree the widget draws (SolarLayers).
  static const Map<String, List<String>> tree = {
    'root': [
      'treeIndent',
      'chevron',
      'checkbox',
      'leadingIcon',
      'label',
      'renameInput',
      'status',
      'tag',
      'counter',
      'buttons',
      'trailingIcon',
    ],
    'chevron': ['chevronChevron', 'iconChevronDown'],
    'buttons': ['iconMore', 'iconPlus'],
  };

  /// Which state wins when several hold, highest first: the MUI recipe's cascade, read backwards.
  static const List<String> statePrecedence = ['edit', 'focus', 'hover'];

  static bool _holds(String state, SolarTreeItemProps p, Set<WidgetState> s) =>
      switch (state) {
        'edit' => p.edit,
        'focus' => s.contains(WidgetState.focused),
        'hover' => s.contains(WidgetState.hovered),
        _ => false,
      };

  /// The entry for one cell under these props and states, by the IR's precedence: a state that
  /// holds beats the resting value, the per-size-and-appearance entry beats the per-appearance
  /// one, and the resting value falls back through appearance, size and base.
  static String? lookup(String cell, SolarTreeItemProps p, Set<WidgetState> s) {
    final combo = 'selected=${p.selected}, expanded=${p.expanded}';
    const size = '';
    for (final state in statePrecedence) {
      if (!_holds(state, p, s)) continue;
      final hit =
          cells['$cell|combined|$size|$combo|$state'] ??
          cells['$cell|appearance|$combo|$state'];
      if (hit != null) return hit;
    }
    return cells['$cell|combined|$size|$combo|default'] ??
        cells['$cell|appearance|$combo|default'] ??
        cells['$cell|size|$size'] ??
        cells['$cell|base'];
  }

  static Color color(
    SolarTheme t,
    String cell,
    SolarTreeItemProps p,
    Set<WidgetState> s,
  ) {
    final c = t.colors;
    return switch (lookup(cell, p, s)) {
      'none' => Colors.transparent,
      't:color.border.feedback.focus.strong' => c.borderFeedbackFocusStrong,
      't:color.icon.primary' => c.iconPrimary,
      't:color.icon.secondary' => c.iconSecondary,
      't:color.surface.active' => c.surfaceActive,
      't:color.surface.base' => c.surfaceBase,
      't:color.surface.hover' => c.surfaceHover,
      't:color.text.primary' => c.textPrimary,
      't:color.text.secondary' => c.textSecondary,
      't:color.text.tertiary' => c.textTertiary,
      final v => throw StateError('$cell: no colour for $v'),
    };
  }

  static List<BoxShadow> shadow(
    SolarTheme t,
    String cell,
    SolarTreeItemProps p,
    Set<WidgetState> s,
  ) => switch (lookup(cell, p, s)) {
    'none' || null => const <BoxShadow>[],
    't:shadow.focus.default' => t.shadows.focusDefault,
    final v => throw StateError('$cell: no shadow for $v'),
  };

  /// A length in logical pixels, or null where the IR says the layer hugs its content.
  static double? dimension(
    String cell,
    SolarTreeItemProps p,
    Set<WidgetState> s,
  ) {
    final v = lookup(cell, p, s);
    if (v == null || v == 'k:HUG') return null;
    if (v == 'k:FILL') return double.infinity;
    if (v.startsWith('px:')) return double.parse(v.substring(3));
    return switch (v) {
      't:border.default' => SolarBorder.$default,
      't:icon.sm' => SolarIconSize.sm,
      't:inset.2xs' => SolarInset.$2xs,
      't:inset.none' => SolarInset.none,
      't:inset.xs' => SolarInset.xs,
      't:radius.control' => SolarRadius.control,
      _ => throw StateError('$cell: no length for $v'),
    };
  }

  static TextStyle? textStyle(
    SolarTheme t,
    String cell,
    SolarTreeItemProps p,
    Set<WidgetState> s,
  ) => switch (lookup(cell, p, s)) {
    'none' || null => null,
    't:typography.label.md' => t.typography.labelMd,
    final v => throw StateError('$cell: no text style for $v'),
  };

  /// Whether a layer is drawn: the shell reads this, the style does not.
  static bool present(String layer, SolarTreeItemProps p, Set<WidgetState> s) =>
      lookup('$layer.present', p, s) != 'b:false';
}
